setup:
using WebCommander.Sdk.Client;
using WebCommander.Sdk.Config;

var auth = new AuthConfig(
    baseUrl: Environment.GetEnvironmentVariable("WC_BASE_URL")!,
    clientId: Environment.GetEnvironmentVariable("WC_CLIENT_ID")!,
    clientSecret: Environment.GetEnvironmentVariable("WC_CLIENT_SECRET")!,
    redirectUri: Environment.GetEnvironmentVariable("WC_REDIRECT_URI")!,
    authString: Environment.GetEnvironmentVariable("WC_AUTH_STRING")!,
    clientName: "default");

await using var client = new WebCommanderClient(new SdkConfig(auth, raiseOnError: true));

list_customers.code:
var response = await client.AdminCustomers.GetCustomersAsync(
    new Dictionary<string, object?> { ["limit"] = 20, ["status"] = "active" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var customer in ((IReadOnlyList<object?>)body["customers"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{customer["customer_id"]} {customer["email"]}");

get_customer.code:
var response = await client.AdminCustomers.GetCustomerAsync(123);
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var customer = (IReadOnlyDictionary<string, object?>)body["customer"]!;
Console.WriteLine(customer["email"]);

