create_customer.code:
var response = await client.AdminCustomers.CreateCustomerAsync(new Dictionary<string, object?>
{
    ["customer"] = new Dictionary<string, object?>
    {
        ["first_name"] = "Jane", ["last_name"] = "Doe", ["email"] = "jane@example.com", ["company"] = false,
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var customer = (IReadOnlyDictionary<string, object?>)body["customer"]!;
Console.WriteLine(customer["customer_id"]);

